import { getNotificationPreference } from "@/lib/data";
import { toggleNotifications } from "./actions";
import { SubmitButton } from "./submit-button";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference("user_1");

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{" "}
        <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>.
      </p>
      <form action={toggleNotifications}>
        <SubmitButton />
      </form>
    </main>
  );
}

