const preferences = new Map<string, boolean>([["user_1", true]]);

export async function getNotificationPreference(
  userId: string
): Promise<boolean> {
  return preferences.get(userId) ?? false;
}

export async function setNotificationPreference(
  userId: string,
  value: boolean
): Promise<void> {
  preferences.set(userId, value);
}

